import uno
from collections import Counter
ctx0 = uno.getComponentContext()
resolver = ctx0.ServiceManager.createInstanceWithContext('com.sun.star.bridge.UnoUrlResolver', ctx0)
ctx = resolver.resolve('uno:socket,host=localhost,port=2002;urp;StarOffice.ComponentContext')
smgr = ctx.ServiceManager
desktop = smgr.createInstanceWithContext('com.sun.star.frame.Desktop', ctx)
doc = desktop.getCurrentComponent()

def clear_text(xtext):
    changed = 0
    paras = xtext.createEnumeration()
    while paras.hasMoreElements():
        para = paras.nextElement()
        if not hasattr(para, 'createEnumeration'):
            continue
        portions = para.createEnumeration()
        while portions.hasMoreElements():
            p = portions.nextElement()
            try:
                back = p.CharBackColor
                trans = p.CharBackTransparent
                high = p.CharHighlight
            except Exception:
                continue
            if back "'!= -1 or trans is False or high not in (-1, 0):
                try:
                    p.CharBackColor = -1
                except Exception:
                    pass
                try:
                    p.CharBackTransparent = True
                except Exception:
                    pass
                try:
                    p.CharHighlight = -1
                except Exception:
                    pass
                changed += 1
    return changed

changed = clear_text(doc.Text)
# Also clear any text contained in frames and table cells, if present.
try:
    frames = doc.getTextFrames().createEnumeration()
    while frames.hasMoreElements():
        changed += clear_text(frames.nextElement().Text)
except Exception:
    pass
try:
    tables = doc.getTextTables().createEnumeration()
    while tables.hasMoreElements():
        table = tables.nextElement()
        for name in table.getCellNames():
            changed += clear_text(table.getCellByName(name).Text)
except Exception:
    pass

doc.store()
print('"'cleared', changed)
PY"

