    paras=xtext.createEnumeration()
    while paras.hasMoreElements():
        para=paras.nextElement()
        if hasattr(para,'createEnumeration'):
            portions=para.createEnumeration()
            while portions.hasMoreElements():
                p=portions.nextElement()
                try: back=p.CharBackColor; trans=p.CharBackTransparent; high=p.CharHighlight
                except Exception: continue
                if back "'!= -1 or trans is False or high not in (-1,0):
                    counts[(back, high, trans)] += 1
                    if len(examples)<10: examples.append((getattr(p,'"'String',''), back, high, trans))
if doc:
    scan_text(doc.Text)
    try:
        frames=doc.getTextFrames().createEnumeration()
        while frames.hasMoreElements(): scan_text(frames.nextElement().Text)
    except Exception: pass
    try:
        tables=doc.getTextTables().createEnumeration()
        while tables.hasMoreElements():
            t=tables.nextElement()
            for n in t.getCellNames(): scan_text(t.getCellByName(n).Text)
    except Exception: pass
print('doc', getattr(doc,'URL',None))
